def single_number(nums):
    result = 0
    for i in range(32):
        bit_sum = 0
        for num in nums:
            bit_sum += (num >> i) & 1
        bit = bit_sum % 3
        if bit:
            result |= (1 << i)
    if result >= 2 ** 31:
        result -= 2 ** 32
    return result

